package com.pharmapack.qms.capa; import com.pharmapack.qms.deviation.Deviation; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="capa_actions") @Getter @Setter @NoArgsConstructor public class CapaAction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="deviation_id") Deviation deviation; String actionType; @Column(name="action_description",columnDefinition="TEXT") String actionDescription; Long ownerId; LocalDate dueDate,completedDate; String status="OPEN"; String effectivenessResult; }
